const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = readInt();
    if (N === null) return;
    const M = readInt();

    const T = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        T[i] = readInt();
    }

    // Ordena T em ordem decrescente
    T.sort();
    // Inverter para ficar decrescente
    for (let i = 0, j = N - 1; i < j; i++, j--) {
        const tmp = T[i];
        T[i] = T[j];
        T[j] = tmp;
    }

    const F = new Int32Array(M);
    for (let i = 0; i < M; i++) {
        F[i] = readInt();
    }

    // Se há pelo menos tantos mecânicos quanto carros, cada carro pode ser o primeiro de um mecânico
    if (N <= M) {
        console.log("0");
        return;
    }

    // Min-heap baseada em arrays paralelos
    const heapVal = new Float64Array(M + 1);
    const heapStep = new Int32Array(M + 1);
    let heapSize = M;

    for (let i = 0; i < M; i++) {
        heapVal[i + 1] = F[i];
        heapStep[i + 1] = F[i];
    }

    // Heapify em O(M)
    for (let i = Math.floor(M / 2); i >= 1; i--) {
        let cur = i;
        const v = heapVal[cur];
        const s = heapStep[cur];
        while ((cur << 1) <= heapSize) {
            let child = cur << 1;
            if (child + 1 <= heapSize && heapVal[child + 1] < heapVal[child]) {
                child++;
            }
            if (heapVal[child] < v) {
                heapVal[cur] = heapVal[child];
                heapStep[cur] = heapStep[child];
                cur = child;
            } else {
                break;
            }
        }
        heapVal[cur] = v;
        heapStep[cur] = s;
    }

    let ans = 0n;

    // Os primeiros M carros pegam coeficiente 0 (custo 0).
    // Para os carros restantes (de M até N-1), pegamos o menor coeficiente da heap.
    for (let i = M; i < N; i++) {
        const curVal = heapVal[1];
        const curStep = heapStep[1];

        ans += BigInt(T[i]) * BigInt(curVal);

        const nextVal = curVal + curStep;

        // Push-down (substitui a raiz por nextVal e restabelece a propriedade da heap)
        let cur = 1;
        while ((cur << 1) <= heapSize) {
            let child = cur << 1;
            if (child + 1 <= heapSize && heapVal[child + 1] < heapVal[child]) {
                child++;
            }
            if (heapVal[child] < nextVal) {
                heapVal[cur] = heapVal[child];
                heapStep[cur] = heapStep[child];
                cur = child;
            } else {
                break;
            }
        }
        heapVal[cur] = nextVal;
        heapStep[cur] = curStep;
    }

    console.log(ans.toString());
}

solve();
